// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

/**
 * Regression coverage for {@code FILTER(CONTAINS(LCASE(?o), "..."))} over long, mixed-case stored literals. Every
 * company below carries a long {@code brands} literal whose substring match is only visible after case folding, so the
 * filter must survive whatever id-level pre-filtering the native engine applies.
 */
public class LmdbLongLiteralContainsFilterTest {

	private static final String EX = "http://company#";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";

	private static final String QUERY = "PREFIX ex: <http://company#>\n"
			+ "SELECT ?cmp ?name ?brands WHERE {\n"
			+ "  ?cmp a ex:Company .\n"
			+ "  ?cmp ex:name ?name .\n"
			+ "  ?cmp ex:brands ?brands .\n"
			+ "  FILTER(CONTAINS(LCASE(?brands), \"gemini\"))\n"
			+ "}";

	/**
	 * Large enough that the row-count gated plans engage: native hash join and merge join both require
	 * {@code minRows=4096} before they are considered.
	 */
	private static final int COMPANIES = 20_000;
	private static final int MATCHING = 5_000;

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.begin();
			ValueFactory vf = conn.getValueFactory();
			IRI company = vf.createIRI(EX, "Company");
			IRI name = vf.createIRI(EX, "name");
			IRI brands = vf.createIRI(EX, "brands");
			IRI type = vf.createIRI("http://www.w3.org/1999/02/22-rdf-syntax-ns#type");

			for (int i = 0; i < COMPANIES; i++) {
				IRI cmp = vf.createIRI(EX, "company" + i);
				conn.add(cmp, type, company);
				conn.add(cmp, name, vf.createLiteral("Company Number " + i));
				conn.add(cmp, brands, vf.createLiteral(brandsLiteral(i)));
			}
			conn.commit();
		}
	}

	/**
	 * Long literal (well past any short-string inlining budget). The first {@link #MATCHING} companies carry a
	 * mixed-case "gemini" token, placed deep inside the text so that prefix-only inspection cannot see it.
	 */
	private static String brandsLiteral(int index) {
		StringBuilder builder = new StringBuilder(2048);
		builder.append("Brand portfolio for company ").append(index).append(": ");
		for (int i = 0; i < 40; i++) {
			builder.append("Filler Brand ").append(index).append('-').append(i).append("; ");
		}
		if (index < MATCHING) {
			builder.append(mixedCaseToken(index)).append(" Holdings; ");
		}
		for (int i = 0; i < 40; i++) {
			builder.append("Trailing Brand ").append(index).append('-').append(i).append("; ");
		}
		return builder.toString();
	}

	private static String mixedCaseToken(int index) {
		char[] token = "gemini".toCharArray();
		for (int i = 0; i < token.length; i++) {
			if (((index >> i) & 1) == 1) {
				token[i] = Character.toUpperCase(token[i]);
			}
		}
		return new String(token);
	}

	/** Repeated evaluation, so warmup-gated compiled kernels get a chance to take over mid-run. */
	@Test
	@Timeout(value = 30)
	public void repeatedEvaluationKeepsEveryMatch() {
		for (int i = 0; i < 8; i++) {
			System.out.println("Iteration " + i + ": native engine enabled = " + System.getProperty(NATIVE_FLAG));
			assertThat(rows(QUERY, true)).as("iteration %d", i).hasSize(MATCHING);
		}
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
	}

	@Test
	public void containsOverLongMixedCaseLiteralsReturnsEveryMatch() {
		assertThat(rows(QUERY, true)).hasSize(MATCHING);
	}

	@Test
	public void nativeEngineAgreesWithInterpretedEngine() {
		assertThat(rows(QUERY, true)).hasSize(rows(QUERY, false).size());
	}

	private List<BindingSet> rows(String query, boolean nativeEnabled) {
		String previous = System.getProperty(NATIVE_FLAG);
		System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEnabled));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}
}
